Lemma INV_requeue : forall pc pb pb' st ql lb qg gb mo,
  INV pc pb st mo ->
  Permutation (qchunks (pb' ++ ql ++ qg)) (qchunks (qbatches pb st)) ->
  zlen (pb' ++ ql ++ qg) = zlen (qbatches pb st) ->
  Forall batch_wf (pb' ++ ql ++ qg) -> lb = bsum ql -> gb = bsum qg ->
